def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def write_complete(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def main() -> int:
    print("=" * 40)
    print(" OIT-001 INSTALLER")
    print(" OPEN INTELLIGENCE TERMINAL FOUNDATION")
    print("=" * 40)
    try:
        if not SOURCE.is_file():
            raise RuntimeError(f"Actual OOR-013 module missing: {SOURCE}")
        source_text = SOURCE.read_text(encoding="utf-8")
        required = (
            'SCHEMA_VERSION = "OOR-013"',
            'ENGINE_ID = "OOR-013"',
            "runtime_complete",
            "immutable_freeze",
            "downstream_read_only_operation_allowed",
            "qseries_execution_allowed",
            "order_creation_allowed",
            "funds_movement_allowed",
            "portfolio_mutation_allowed",
        )
        missing = [item for item in required if item not in source_text]
        if missing:
            raise RuntimeError(f"OOR-013 contract incomplete: {missing}")
        ast.parse(source_text, filename=str(SOURCE))
        protected_hash = sha256(SOURCE)
        print("[OK] Actual OOR-013 final completion and freeze contract verified")

        write_complete(PRODUCTION, PRODUCTION_SOURCE)
        write_complete(RUNNER, RUNNER_SOURCE)
        write_complete(TEST, TEST_SOURCE)

        export = "from .oracle_open_intelligence_terminal_foundation import *"
        current = INIT.read_text(encoding="utf-8") if INIT.exists() else ""
        if export not in current.splitlines():
            if current and not current.endswith("\n"):
                current += "\n"
            INIT.write_text(current + export + "\n", encoding="utf-8", newline="\n")
            print(f"[OK] PACKAGE UPDATED: {INIT.resolve()}")
        else:
            print(f"[OK] PACKAGE EXPORT PRESENT: {INIT.resolve()}")
        ast.parse(INIT.read_text(encoding="utf-8"), filename=str(INIT))

        completed = subprocess.run([sys.executable, str(TEST)], cwd=ROOT, check=False)
        if completed.returncode:
            raise RuntimeError(f"OIT-001 test failed with exit code {completed.returncode}")
        if sha256(SOURCE) != protected_hash:
            raise RuntimeError("Protected OOR-013 module changed")

        print("[PASS] Protected OOR-013 module unchanged")
        print("[PASS] Oracle Terminal created as a separate read-only package")
        print("[PASS] Open-domain capability commands installed")
        print("[PASS] Interactive terminal runner installed")
        print("[PASS] No acquisition, analytics, research-response, Operator Runtime, or Q Series module modified")
        print(f"[PASS] Repository located: {ROOT}")
        print("[DONE] OIT-001 OPEN INTELLIGENCE TERMINAL FOUNDATION INSTALLED")
        return 0
    except (RuntimeError, SyntaxError) as exc:
        print(f"[ERROR] {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
